namespace Infrastructure.Database.Maintenance;




internal static class MaintenanceScript
{
    public const string UspMaintainDatabase = @"CREATE OR ALTER PROCEDURE dbo.usp_MaintainDatabase\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SET XACT_ABORT ON;\n\n    DECLARE @dbName sysname = DB_NAME();\n    DECLARE @logFileId int = (SELECT file_id FROM sys.database_files WHERE type = 1);\n    DECLARE @dataFileId int = (SELECT file_id FROM sys.database_files WHERE type = 0);\n    DECLARE @logSizeMB int = 512;\n    DECLARE @dataSizeMB int = 512;\n\n    -- بازگرداندن autogrowth به حالت درصدی (در صورت دستی بودن)\n    DECLARE @fileId int, @growth int;\n    DECLARE growthCursor CURSOR LOCAL FAST_FORWARD FOR\n        SELECT file_id, growth FROM sys.database_files WHERE is_percent_growth = 0;\n\n    OPEN growthCursor;\n    FETCH NEXT FROM growthCursor INTO @fileId, @growth;\n    WHILE @@FETCH_STATUS = 0\n    BEGIN\n        EXEC('ALTER DATABASE ' + QUOTENAME(@dbName) + ' MODIFY FILE (NAME = ' +\n             QUOTENAME((SELECT name FROM sys.database_files WHERE file_id = @fileId)) +\n             ', FILEGROWTH = 10 PERCENT)');\n        FETCH NEXT FROM growthCursor INTO @fileId, @growth;\n    END\n    CLOSE growthCursor;\n    DEALLOCATE growthCursor;\n\n    -- کوچک‌سازی فایل داده\n    IF EXISTS (SELECT 1 FROM sys.database_files WHERE file_id = @dataFileId)\n    BEGIN\n        EXEC('DBCC SHRINKFILE (' + CAST(@dataFileId AS varchar(10)) + ', ' +\n             CAST(@dataSizeMB AS varchar(10)) + ') WITH NO_INFOMSGS');\n    END\n\n    -- کوچک‌سازی فایل لاگ\n    IF EXISTS (SELECT 1 FROM sys.database_files WHERE file_id = @logFileId)\n    BEGIN\n        EXEC('DBCC SHRINKFILE (' + CAST(@logFileId AS varchar(10)) + ', ' +\n             CAST(@logSizeMB AS varchar(10)) + ') WITH NO_INFOMSGS');\n    END;\n\n    SELECT\n        CAST(FILEPROPERTY(DB_NAME() + '.dbsize', 'SpaceUsed') / 128.0 / 1024 AS DECIMAL(10,2)) AS used_gb,\n        (SELECT CAST(SUM(size) / 128.0 / 1024 AS DECIMAL(10,2)) FROM sys.database_files) AS allocated_gb;\nEND;";
}
